import operator
import re
import sys
import threading

CYCLE = "#CYCLE!"
DIV0 = "#DIV/0!"

_TOKEN = re.compile(r"\s*(SUM|MIN|MAX|IF|[A-Z][1-9][0-9]?|[0-9]+|<>|<=|>=|[-+*/()=<>,:])")
_COMPARE = {
    "=": operator.eq,
    "<>": operator.ne,
    "<": operator.lt,
    "<=": operator.le,
    ">": operator.gt,
    ">=": operator.ge,
}


class _Err(Exception):
    def __init__(self, value):
        super().__init__(value)
        self.value = value


def _tokenize(s):
    tokens = []
    pos = 0
    s = s.rstrip()
    while pos < len(s):
        m = _TOKEN.match(s, pos)
        if not m:
            raise ValueError("bad token at %d in %r" % (pos, s))
        tokens.append(m.group(1))
        pos = m.end()
    return tokens


class _Parser:
    def __init__(self, toks):
        self.t = toks
        self.i = 0

    def peek(self, k=0):
        j = self.i + k
        return self.t[j] if j < len(self.t) else None

    def next(self):
        tok = self.t[self.i]
        self.i += 1
        return tok

    def expect(self, tok):
        if self.next() != tok:
            raise ValueError("expected " + tok)

    def formula(self):
        node = self.term()
        while self.peek() in ("+", "-"):
            op = self.next()
            node = ("bin", op, node, self.term())
        return node

    def term(self):
        node = self.unary()
        while self.peek() in ("*", "/"):
            op = self.next()
            node = ("bin", op, node, self.unary())
        return node

    def unary(self):
        if self.peek() == "-":
            self.next()
            return ("neg", self.unary())
        return self.atom()

    def atom(self):
        tok = self.next()
        if tok == "(":
            node = self.formula()
            self.expect(")")
            return node
        if tok.isdigit():
            return ("num", int(tok))
        if tok == "IF":
            self.expect("(")
            left = self.formula()
            op = self.next()
            right = self.formula()
            self.expect(",")
            then = self.formula()
            self.expect(",")
            other = self.formula()
            self.expect(")")
            return ("if", left, op, right, then, other)
        if tok in ("SUM", "MIN", "MAX"):
            self.expect("(")
            args = [self.arg()]
            while self.peek() == ",":
                self.next()
                args.append(self.arg())
            self.expect(")")
            return ("call", tok, args)
        return ("ref", tok)

    def arg(self):
        if self.peek(1) == ":":
            a = self.next()
            self.next()
            b = self.next()
            c1, c2 = ord(a[0]) - 65, ord(b[0]) - 65
            r1, r2 = int(a[1:]), int(b[1:])
            return ("range", min(c1, c2), min(r1, r2), max(c1, c2), max(r1, r2))
        return self.formula()


def _parse(s):
    return _Parser(_tokenize(s)).formula()


def _div(a, b):
    if b == 0:
        raise _Err(DIV0)
    q = abs(a) // abs(b)
    return q if (a < 0) == (b < 0) else -q


def _solve(cells):
    done = {}
    active = set()

    def value_of(name):
        # Returns an int or an error string; never raises.
        if name in done:
            return done[name]
        if name in active:
            return CYCLE
        content = cells[name].strip()
        if not content.startswith("="):
            v = int(content)
            done[name] = v
            return v
        active.add(name)
        try:
            v = ev(_parse(content[1:]))
        except _Err as e:
            v = e.value
        finally:
            active.discard(name)
        done[name] = v
        return v

    def ref(name):
        if name not in cells:
            return 0
        v = value_of(name)
        if isinstance(v, str):
            raise _Err(v)
        return v

    def call(fname, args):
        vals = []
        for a in args:
            if a[0] == "range":
                _, c1, r1, c2, r2 = a
                for r in range(r1, r2 + 1):
                    for c in range(c1, c2 + 1):
                        nm = chr(65 + c) + str(r)
                        if nm in cells:
                            vals.append(ref(nm))
            else:
                vals.append(ev(a))
        if fname == "SUM":
            return sum(vals)
        if not vals:
            return 0
        return min(vals) if fname == "MIN" else max(vals)

    def ev(node):
        kind = node[0]
        if kind == "num":
            return node[1]
        if kind == "ref":
            return ref(node[1])
        if kind == "neg":
            return -ev(node[1])
        if kind == "bin":
            op = node[1]
            a = ev(node[2])
            b = ev(node[3])
            if op == "+":
                return a + b
            if op == "-":
                return a - b
            if op == "*":
                return a * b
            return _div(a, b)
        if kind == "if":
            _, lnode, op, rnode, tnode, enode = node
            lv = ev(lnode)
            rv = ev(rnode)
            branch = tnode if _COMPARE[op](lv, rv) else enode
            return ev(branch)
        if kind == "call":
            return call(node[1], node[2])
        raise ValueError("unknown node " + kind)

    return {name: value_of(name) for name in cells}


def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    # The evaluator recurses along reference chains, which can span every cell,
    # so run it on a thread with a large stack and a high recursion limit.
    result = {}
    error = []

    def run():
        try:
            result.update(_solve(cells))
        except BaseException as e:  # re-raised in the caller below
            error.append(e)

    sys.setrecursionlimit(1000000)
    threading.stack_size(256 * 1024 * 1024)
    t = threading.Thread(target=run)
    t.start()
    threading.stack_size(0)
    t.join()
    if error:
        raise error[0]
    return {name: result[name] for name in cells}
